<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';
import { adminApi,money } from '../api';
import type { AdminOrder,AdminOrderPage,AdminOrderQuery,CatalogResponse } from '../types';
import CheckInScanner from './CheckInScanner.vue';
const props=defineProps<{catalog:CatalogResponse}>();
const query=reactive<AdminOrderQuery>({status:'',technicianId:'',serviceId:'',workId:'',dateFrom:'',dateTo:'',query:'',page:1,limit:30,sortBy:'startAt',sortDirection:'desc'});
const result=ref<AdminOrderPage>({orders:[],canRefund:false,page:1,limit:30,total:0,pages:1});const loading=ref(false);const error=ref('');const notice=ref('');const refunding=ref<Record<string,boolean>>({});
const availableWorks=computed(()=>props.catalog.works.filter(item=>!query.serviceId||item.serviceId===query.serviceId));
function refundLabel(status=''){return ({INIT:'退款待提交',PENDING_CONFIG:'退款待配置',SUBMITTING:'退款提交中',PROCESSING:'退款处理中',SUCCESS:'退款已到账',RETRY_REQUIRED:'退款需重新发起',WAITING_FUNDS:'商户余额不足',CONFIG_OR_DATA_ERROR:'退款配置异常',MANUAL_ACTION:'退款需人工处理',CLOSED:'退款已关闭',ABNORMAL:'退款异常'} as Record<string,string>)[status]||'';}
function canRefund(order:AdminOrder){return result.value.canRefund&&['RESERVED','ARRIVED','IN_SERVICE','COMPLETED','NO_SHOW_REVIEW','CANCEL_PENDING_REFUND','CANCELLED_BY_USER','CANCELLED_NO_SHOW'].includes(order.status)&&['NOT_REQUIRED','RETRY_REQUIRED','CLOSED','WAITING_FUNDS','CONFIG_OR_DATA_ERROR'].includes(order.refundStatus||'NOT_REQUIRED');}
async function load(page=query.page||1){query.page=page;loading.value=true;error.value='';try{result.value=await adminApi.orders({...query});}catch(err){error.value=err instanceof Error?err.message:'订单加载失败';}finally{loading.value=false;}}
function reset(){Object.assign(query,{status:'',technicianId:'',serviceId:'',workId:'',dateFrom:'',dateTo:'',query:'',page:1,limit:30,sortBy:'startAt',sortDirection:'desc'});load();}
async function refund(order:AdminOrder){if(!window.confirm(`确认对订单 ${order.id} 发起退款？`))return;refunding.value[order.id]=true;try{await adminApi.refund(order.id,'管理员在预约订单页发起退款');notice.value='退款请求已提交，最终状态以微信回调或主动查单为准。';await load();}catch(err){error.value=err instanceof Error?err.message:'退款失败';}finally{refunding.value[order.id]=false;}}
onMounted(()=>load());
</script>

<template><section class="page-section orders-workspace"><div class="page-intro"><div><h1>预约订单</h1><p>按日期、顾客、项目、款式、技师与状态组合检索，共 {{result.total}} 单</p></div><button class="soft-button" :disabled="loading" @click="load()">{{loading?'加载中…':'刷新'}}</button></div><CheckInScanner @checked-in="message=>{notice=message;load()}"/><div class="order-filter-panel"><label class="order-search">搜索<input v-model="query.query" placeholder="订单号 / 顾客 / 手机 / 款式" @keyup.enter="load(1)"/></label><label>开始日期<input v-model="query.dateFrom" type="date"/></label><label>结束日期<input v-model="query.dateTo" type="date"/></label><label>状态<select v-model="query.status"><option value="">全部状态</option><option value="PENDING_PAYMENT">待付款</option><option value="RESERVED">待到店</option><option value="ARRIVED">已到店</option><option value="IN_SERVICE">服务中</option><option value="COMPLETED">已完成</option><option value="CANCELLED_NO_SHOW">未到店已取消</option><option value="CANCEL_PENDING_REFUND">退款待处理</option><option value="REFUNDED">已退款</option><option value="CANCELLED_BY_USER">用户取消</option></select></label><label>技师<select v-model="query.technicianId"><option value="">全部技师</option><option v-for="item in catalog.technicians" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>项目<select v-model="query.serviceId" @change="query.workId=''"><option value="">全部项目</option><option v-for="item in catalog.services" :key="item.id" :value="item.id">{{item.categoryName}} · {{item.name}}</option></select></label><label>款式<select v-model="query.workId"><option value="">全部款式</option><option v-for="item in availableWorks" :key="item.id" :value="item.id">{{item.title}}</option></select></label><label>排序<select v-model="query.sortBy"><option value="startAt">预约时间</option><option value="createdAt">下单时间</option><option value="paidFen">实付金额</option></select></label><label>方向<select v-model="query.sortDirection"><option value="desc">由新到旧</option><option value="asc">由旧到新</option></select></label><div class="order-filter-actions"><button class="primary-button" @click="load(1)">查询</button><button class="soft-button" @click="reset">清空</button></div></div><p v-if="error" class="field-error">{{error}}</p><p v-if="notice" class="inline-success">{{notice}}</p><section class="panel table-panel"><table><thead><tr><th>预约时间</th><th>项目 / 技师</th><th>顾客</th><th>状态</th><th>金额</th><th>操作</th></tr></thead><tbody><tr v-for="order in result.orders" :key="order.id"><td><strong>{{order.startAtLabel}}</strong><small>{{order.id}}</small></td><td><strong>{{order.serviceName}}</strong><small v-if="order.work">{{order.work.title}}</small><small>{{order.technicianName}}</small></td><td><strong>{{order.customerName||'—'}}</strong><small>{{order.phoneMasked||'按权限展示'}}</small></td><td><span :class="['pill',order.status==='COMPLETED'?'green':order.status==='RESERVED'?'rose':'sand']">{{order.statusLabel}}</span><small v-if="refundLabel(order.refundStatus)">{{refundLabel(order.refundStatus)}}</small></td><td class="money-cell">{{money(order.paidFen)}}<small v-if="order.refundAmountFen">退款 {{money(order.refundAmountFen)}}</small></td><td><button v-if="canRefund(order)" class="link-action danger-link" :disabled="refunding[order.id]" @click="refund(order)">{{refunding[order.id]?'提交中…':'发起退款'}}</button><span v-else class="muted-cell">—</span></td></tr></tbody></table><div v-if="!result.orders.length&&!loading" class="empty-inline">没有符合条件的订单。</div></section><div class="order-pagination"><button class="soft-button" :disabled="result.page<=1||loading" @click="load(result.page-1)">上一页</button><span>第 {{result.page}} / {{result.pages}} 页</span><button class="soft-button" :disabled="result.page>=result.pages||loading" @click="load(result.page+1)">下一页</button></div></section></template>
